// Market clock and research charts. Data comes from data.js (generated by research/gapscan).
(function () {
  "use strict";
  const WINDOWS = window.BELLGUARD_WINDOWS || [];
  const DAY = 86400;

  function fmtDuration(sec) {
    sec = Math.max(0, Math.floor(sec));
    const d = Math.floor(sec / DAY);
    const h = Math.floor((sec % DAY) / 3600);
    const m = Math.floor((sec % 3600) / 60);
    const s = sec % 60;
    const pad = (n) => String(n).padStart(2, "0");
    return (d ? d + "d " : "") + pad(h) + "h " + pad(m) + "m " + pad(s) + "s";
  }

  function fmtUtc(ts) {
    const d = new Date(ts * 1000);
    return d.toLocaleString("en-GB", {
      weekday: "short", day: "numeric", month: "short", hour: "2-digit", minute: "2-digit", timeZone: "UTC",
    }) + " UTC";
  }

  /** Current market state from the published closed windows. */
  function marketState(now) {
    for (const [start, end, label] of WINDOWS) {
      if (now >= start && now < end) return { closed: true, until: end, label };
      if (start > now) return { closed: false, until: start, label };
    }
    return { closed: false, until: null, label: null };
  }
  window.bellguardMarketState = marketState;

  function renderClock() {
    const root = document.getElementById("clock");
    if (!root) return;
    const now = Date.now() / 1000;
    const st = marketState(now);
    const pill = root.querySelector(".pill");
    pill.className = "pill " + (st.closed ? "closed" : "open");
    pill.textContent = st.closed ? "Market closed" : "Market open";
    root.querySelector(".countdown").textContent = st.until ? fmtDuration(st.until - now) : "--";
    root.querySelector(".sub").textContent = st.until
      ? (st.closed ? "Reopens " : "Next close (" + st.label + ") ") + fmtUtc(st.until)
      : "No windows published beyond this date.";
    const premium = root.querySelector("[data-premium]");
    if (premium) premium.textContent = st.closed ? "Cover premium active on swaps" : "No premium while open";

    // Week strip: Monday 00:00 UTC to next Monday
    const d = new Date(now * 1000);
    const dow = (d.getUTCDay() + 6) % 7; // Monday = 0
    const weekStart = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) / 1000 - dow * DAY;
    const weekEnd = weekStart + 7 * DAY;
    const track = root.querySelector(".track");
    track.querySelectorAll(".closedseg").forEach((n) => n.remove());
    for (const [start, end] of WINDOWS) {
      if (end <= weekStart || start >= weekEnd) continue;
      const a = (Math.max(start, weekStart) - weekStart) / (7 * DAY);
      const b = (Math.min(end, weekEnd) - weekStart) / (7 * DAY);
      const seg = document.createElement("div");
      seg.className = "closedseg";
      seg.style.left = a * 100 + "%";
      seg.style.width = (b - a) * 100 + "%";
      track.appendChild(seg);
    }
    root.querySelector(".now").style.left = ((now - weekStart) / (7 * DAY)) * 100 + "%";
  }

  function renderFindings() {
    const data = window.BELLGUARD_FINDINGS;
    const host = document.getElementById("findings");
    if (!data || !host) return;
    const rows = data.rows.filter((r) => r.swaps > 0);
    const lost = rows.filter((r) => r.markout < 0);
    const net = rows.reduce((a, r) => a + r.markout, 0);
    const maxGap = rows.reduce((a, r) => Math.max(a, Math.abs(r.gap)), 0);
    const set = (k, v) => { const el = host.querySelector("[data-stat='" + k + "']"); if (el) el.textContent = v; };
    set("windows", rows.length);
    set("lost", lost.length + " of " + rows.length);
    set("net", (net < 0 ? "-$" : "+$") + Math.abs(net).toLocaleString("en-US"));
    set("maxgap", maxGap.toFixed(2) + "%");

    // Scatter: x = weekend, y = reopen gap; colour = LP gained or lost
    const svg = host.querySelector("svg");
    const W = 860, H = 320, L = 54, R = 16, T = 16, B = 56;
    const dates = [...new Set(rows.map((r) => r.date))].sort();
    const pools = [...new Set(rows.map((r) => r.pool))].sort();
    const yMax = Math.max(2, Math.ceil(maxGap));
    const x = (dt) => L + (dates.indexOf(dt) + 0.5) * ((W - L - R) / dates.length);
    const y = (g) => T + (1 - (g + yMax) / (2 * yMax)) * (H - T - B);
    const ns = "http://www.w3.org/2000/svg";
    const el = (tag, attrs, text) => {
      const n = document.createElementNS(ns, tag);
      for (const k in attrs) n.setAttribute(k, attrs[k]);
      if (text != null) n.textContent = text;
      svg.appendChild(n);
      return n;
    };
    svg.setAttribute("viewBox", "0 0 " + W + " " + H);
    svg.innerHTML = "";
    for (let g = -yMax; g <= yMax; g += yMax / 2) {
      el("line", { x1: L, x2: W - R, y1: y(g), y2: y(g), stroke: "var(--rule)", "stroke-width": g === 0 ? 1.5 : 1 });
      el("text", { x: L - 8, y: y(g) + 4, "text-anchor": "end" }, (g > 0 ? "+" : "") + g.toFixed(1) + "%");
    }
    dates.forEach((dt, i) => {
      if (i % 2 === 0) el("text", { x: x(dt), y: H - B + 18, "text-anchor": "middle" }, dt.slice(5));
    });
    el("text", { x: L, y: H - 6 }, "Weekend starting (month-day), all pools");
    rows.forEach((r) => {
      const offset = (pools.indexOf(r.pool) - (pools.length - 1) / 2) * 5;
      const c = el("circle", {
        cx: x(r.date) + offset, cy: y(r.gap), r: 4.5,
        fill: r.markout < 0 ? "var(--chart-loss)" : "var(--chart-gain)", "fill-opacity": 0.85,
      });
      const t = document.createElementNS(ns, "title");
      t.textContent = r.pool + " " + r.date + ": gap " + r.gap.toFixed(2) + "%, LP " +
        (r.markout < 0 ? "lost $" : "gained $") + Math.abs(r.markout).toLocaleString("en-US");
      c.appendChild(t);
    });

    // Per-pool table
    const tbody = host.querySelector("tbody");
    tbody.innerHTML = "";
    for (const p of pools) {
      const rs = rows.filter((r) => r.pool === p);
      const sum = rs.reduce((a, r) => a + r.markout, 0);
      const worst = rs.reduce((a, r) => Math.min(a, r.markout), Infinity);
      const big = rs.reduce((a, r) => Math.max(a, Math.abs(r.gap)), 0);
      const tr = document.createElement("tr");
      tr.innerHTML =
        "<td>" + p + "</td><td>" + rs.length + "</td>" +
        "<td>" + rs.filter((r) => r.markout < 0).length + "</td>" +
        "<td class='" + (sum < 0 ? "loss" : "gain") + "'>" + (sum < 0 ? "-$" : "+$") + Math.abs(sum).toLocaleString("en-US") + "</td>" +
        "<td class='" + (worst < 0 ? "loss" : "gain") + "'>" + (worst < 0 ? "-$" : "+$") + Math.abs(worst).toLocaleString("en-US") + "</td>" +
        "<td>" + big.toFixed(2) + "%</td>";
      tbody.appendChild(tr);
    }
  }

  renderClock();
  renderFindings();
  setInterval(renderClock, 1000);
})();
